//! libren_core.a for the Zig entry: the C-ABI exports of the slice
//! (README § Contract), the root panic handler, the deque test ABI and the
//! layout table. Layouts come from `zig translate-c -lc slice.h` (module
//! "slice", generated by build.sh into the outdir).
const std = @import("std");
const sl = @import("slice");
const core = @import("core.zig");
const drv = @import("drv.zig");
const DQ = @import("dq.zig");
const A = @import("alloc.zig");
const layout_list = @import("layout_list");

// ------------------------------------------------------------------ panic
/// The root panic handler (ReleaseSafe and Debug): every safety trap
/// (overflow, bounds, unreachable, null unwrap) and every @panic ends in
/// the harness's abort path: the message on stderr, then libc abort(), which
/// is what the harness tests, ASan-style tooling and libFuzzer all count.
fn renPanic(msg: []const u8, ra: ?usize) noreturn {
    _ = ra;
    const pre = "ren zig panic: ";
    _ = std.c.write(2, pre, pre.len);
    _ = std.c.write(2, msg.ptr, msg.len);
    _ = std.c.write(2, "\n", 1);
    std.c.abort();
}
pub const panic = std.debug.FullPanic(renPanic);

// Zig 0.17's objects carry no .note.GNU-stack section, so GNU ld warns
// ("missing .note.GNU-stack section implies executable stack") and marks the
// whole program's stack executable. Emit the note ourselves.
comptime {
    asm (".section .note.GNU-stack,\"\",@progbits\n.previous");
}

// ------------------------------------------------------------------ host ABI (9)
export fn ren_start(cfg: [*c]const sl.ren_config, main: sl.ren_main_fn, host: [*c]const sl.ren_host, hostp: ?*anyopaque) ?*sl.ren_core {
    return core.start(cfg, main, host, hostp);
}
export fn ren_thread_init(c: ?*sl.ren_core, worker: i32, stack_lo: ?*anyopaque, stack_size: usize) void {
    core.threadInit(core.coreOf(c), worker, stack_lo, stack_size);
}
export fn ren_run(c: ?*sl.ren_core, worker: i32, steps: u32) i32 {
    return core.run(core.coreOf(c), worker, steps);
}
export fn ren_poll_call(c: ?*sl.ren_core, worker: i32, out: [*c]sl.ren_call) bool {
    return core.pollCall(core.coreOf(c), worker, @ptrCast(out.?));
}
export fn ren_reply(c: ?*sl.ren_core, r: [*c]const sl.ren_reply_t) i32 {
    return core.reply(core.coreOf(c), @ptrCast(r.?));
}
export fn ren_stop(c: ?*sl.ren_core) void {
    core.stop(core.coreOf(c));
}
export fn ren_kill(c: ?*sl.ren_core) void {
    core.kill(core.coreOf(c));
}
export fn ren_free(c: ?*sl.ren_core) void {
    if (c == null) return;
    core.free(core.coreOf(c));
}
export fn ren_progress(c: ?*sl.ren_core, worker: i32) u64 {
    return core.progress(core.coreOf(c), worker);
}

// ------------------------------------------------------------------ emitted-code ABI (7)
export fn ren_spawn(cx: ?*sl.ren_ctx, t: [*c]sl.ren_task) void {
    core.spawn(cx, t);
}
export fn ren_notify(cx: ?*sl.ren_ctx, t: [*c]sl.ren_task) void {
    core.notifyExport(cx, t);
}
export fn ren_world(cx: ?*sl.ren_ctx, self: [*c]sl.ren_task, aw: [*c]sl.ren_await, op: u32, body: [*c]const sl.ren_io_body) i32 {
    return core.world(cx, self, aw, op, body);
}
export fn ren_cancel(cx: ?*sl.ren_ctx, id: u64) void {
    core.cancel(cx, id);
}
export fn ren_tick(cx: ?*sl.ren_ctx) bool {
    return core.tick(cx);
}
export fn ren_cancelled(cx: ?*sl.ren_ctx) bool {
    return core.cancelled(cx);
}
export fn ren_ctx_worker(cx: ?*sl.ren_ctx) i32 {
    return core.ctxWorker(cx);
}

// ------------------------------------------------------------------ driver entry (6)
export fn ren_drv_new(o: [*c]const sl.ren_drv_opts) ?*sl.ren_drv {
    return drv.new(o);
}
export fn ren_drv_host(d: ?*sl.ren_drv, hostp: [*c]?*anyopaque) [*c]const sl.ren_host {
    return drv.host(d, hostp);
}
export fn ren_drv_worker(d: ?*sl.ren_drv, c: ?*sl.ren_core, worker: i32) i32 {
    return drv.worker(d, c, worker);
}
export fn ren_drv_finish(d: ?*sl.ren_drv, c: ?*sl.ren_core) i32 {
    return drv.finish(d, c);
}
export fn ren_drv_free(d: ?*sl.ren_drv) void {
    drv.free(d);
}
export fn ren_drv_last_error(d: ?*sl.ren_drv) [*c]const u8 {
    return drv.lastError(d);
}

// ------------------------------------------------------------------ deque test ABI (5)
const U64Deque = DQ.Deque(u64);
inline fn dqOf(q: ?*sl.ren_dq) *U64Deque {
    return @ptrCast(@alignCast(q.?)); // ptr site: opaque ren_dq -> deque
}
export fn ren_dq_new(log2: u32) ?*sl.ren_dq {
    const q = A.create(U64Deque);
    q.init(log2);
    return @ptrCast(q); // ptr site: deque -> opaque ren_dq
}
export fn ren_dq_push(q: ?*sl.ren_dq, v: u64) void {
    dqOf(q).push(v);
}
export fn ren_dq_take(q: ?*sl.ren_dq) u64 {
    return dqOf(q).take() orelse sl.REN_DQ_EMPTY;
}
export fn ren_dq_steal(q: ?*sl.ren_dq) u64 {
    return switch (dqOf(q).steal()) {
        .empty => sl.REN_DQ_EMPTY,
        .abort => sl.REN_DQ_ABORT,
        .item => |x| x,
    };
}
export fn ren_dq_free(q: ?*sl.ren_dq) void {
    const d = dqOf(q);
    d.deinit();
    A.destroy(d);
}

// ------------------------------------------------------------------ layout table (1)
// layout_list.entries is REN_LAYOUT_LIST expanded by the C preprocessor at
// build time (build.sh): (name, type, field) triples. The values are Zig's
// own view of the translate-c types: @offsetOf / @sizeOf.
const layout_n = layout_list.entries.len;
const layout_table: [layout_n]sl.ren_layout_ent = blk: {
    var t: [layout_n]sl.ren_layout_ent = undefined;
    for (layout_list.entries, 0..) |e, i| {
        // e = .{ "type", "field" or "", type }
        const v = if (e[1].len == 0) @sizeOf(e[2]) else @offsetOf(e[2], e[1]);
        const name = if (e[1].len == 0) "sizeof(" ++ e[0] ++ ")" else e[0] ++ "." ++ e[1];
        t[i] = .{ .name = name, .value = v, ._pad = 0 };
    }
    break :blk t;
};
export fn ren_layout_table(out: [*c][*c]const sl.ren_layout_ent) usize {
    out.* = &layout_table;
    return layout_n;
}
